<script setup>import TwinalyzeAnalytics from '@twinalyze/web-analytics';import {ref} from 'vue';import {useAuth} from '../stores/auth';import {useCart} from '../stores/cart';const auth=useAuth(),cart=useCart(),email=ref(auth.user.value?.email||'customer@example.com'),first=ref(auth.user.value?.name?.split(' ')[0]||'Nivora'),last=ref('Customer'),address=ref('18 Studio Lane'),city=ref('Portland'),postal=ref('97205'),done=ref('');const complete=()=>{const orderId=`NIV-${Date.now().toString().slice(-8)}`;TwinalyzeAnalytics.track('purchaseCompleted',{orderId,userId:auth.user.value?.email||email.value,revenue:cart.subtotal.value,itemCount:cart.count.value,currency:'USD',source:'nivora_vue_npm_store',products:cart.items.value.map(i=>({productId:i.product.id,productName:i.product.name,price:i.product.price,quantity:i.quantity}))});done.value=orderId;cart.clear();};</script>
<template><section class="page"><span>DEMO CHECKOUT</span><h1>Final details.</h1><p>Submit the form to test form interactions and purchaseCompleted.</p><div v-if="done" class="success"><b>✓</b><h2>Order complete.</h2><p>Demo order <strong>{{done}}</strong> was recorded.</p><RouterLink class="solid-button" to="/products">Continue browsing</RouterLink></div><div v-else-if="cart.items.value.length" class="layout"><form @submit.prevent="complete"><h2>Contact</h2><label>Email<input v-model="email" name="email" type="email" required/></label><h2>Delivery</h2><div class="row"><label>First name<input v-model="first" name="first" required/></label><label>Last name<input v-model="last" name="last" required/></label></div><label>Address<input v-model="address" name="address" required/></label><div class="row"><label>City<input v-model="city" name="city" required/></label><label>Postal code<input v-model="postal" name="postal" required/></label></div><button>Complete demo order</button></form><aside><span>YOUR ORDER</span><div v-for="i in cart.items.value" :key="i.product.id"><p>{{i.product.name}} × {{i.quantity}}</p><strong>${{i.product.price*i.quantity}}</strong></div><div><p>Total</p><strong>${{cart.subtotal.value}}</strong></div></aside></div><div v-else class="success"><h2>No items to check out.</h2><RouterLink class="solid-button" to="/products">Browse products</RouterLink></div></section></template>
<style scoped>.page{padding:70px 7vw}.page>span,aside>span{color:var(--coral-dark);font-size:10px;font-weight:900;letter-spacing:.18em}h1{margin:12px 0 8px;font:400 clamp(56px,7vw,90px)/.92 Georgia}.page>p{color:var(--muted)}.layout{margin-top:38px;display:grid;grid-template-columns:1fr 390px;gap:42px;align-items:start}form{padding:34px;border:1px solid var(--line);border-radius:28px;background:#fffdf8}form h2{margin:0 0 18px;font:400 30px Georgia}form h2:not(:first-child){margin-top:32px}label{display:block;margin-bottom:16px;font-size:12px;font-weight:900}input{width:100%;box-sizing:border-box;margin-top:7px;padding:14px;border:1px solid var(--line);border-radius:13px;background:var(--page);font:inherit}.row{display:grid;grid-template-columns:1fr 1fr;gap:14px}form button{width:100%;padding:15px;border:0;border-radius:999px;background:var(--ink);color:white;font-weight:900}aside{padding:28px;border-radius:28px;background:var(--sage)}aside div{display:flex;justify-content:space-between;border-bottom:1px solid rgba(31,35,31,.15)}.success{margin-top:40px;padding:78px 20px;text-align:center;border-radius:30px;background:var(--cream)}.success b{width:72px;height:72px;margin:auto;display:grid;place-items:center;border-radius:50%;background:var(--forest);color:white;font-size:32px}.success h2{font:400 44px Georgia}@media(max-width:850px){.layout{grid-template-columns:1fr}}@media(max-width:560px){.page{padding-inline:20px}.row{grid-template-columns:1fr;gap:0}}</style>
